/**
 * 对 c_menu_group 为 null 的存量菜单填充 web/h5 分组，并回写 componentModel
 * 仅填充 null 的菜单，已配置分组（非 null）的菜单不做任何改动
 * 一次批量调用 componentModel batchUpdateComponentMenu，componentModel 侧逐条 UPDATE
 *
 * @param componentIdentification 组件标识
 * @param menuMapList             菜单列表（componentModel queryComponentMenu 返回，key 为表列名）
 */
private void fillMenuGroupIfNull(String componentIdentification, List<Map<String, Object>> menuMapList) {
    List<Map<String, Object>> toUpdateList = new ArrayList<>();
    for (Map<String, Object> menu : menuMapList) {
        Object menuGroupValue = menu.get("c_menu_group");
        if (menuGroupValue != null && StringUtils.isNotBlank(String.valueOf(menuGroupValue))) {
            continue;
        }
        //只回写 id + c_menu_group，避免把整行字段都覆盖一遍
        Map<String, Object> updateItem = new HashMap<>();
        updateItem.put("id", menu.get("id"));
        updateItem.put("c_menu_group", resolveMenuGroup(menu));
        toUpdateList.add(updateItem);
    }
    if (CollectionUtils.isNotEmpty(toUpdateList)) {
        logger.info("fillMenuGroupIfNull update count:{}, componentIdentification:{}", toUpdateList.size(), componentIdentification);
        componentModelClient.batchUpdateComponentMenu(JSONObject.toJSONString(toUpdateList, SerializerFeature.WriteMapNullValue), componentIdentification);
    }
}

 * 优化：1 次批量存在性校验 + 1 次 CASE WHEN 批量 UPDATE，DB 往返从 2N 降到 2
 */
@Override
public int batchUpdateComponentMenu(String params, String c_component_id) throws Exception {
    // 去掉转义字符、第一个和最后一个"
    if (params.startsWith("\"")) {
        params = StringEscapeUtils.unescapeJava(params);
        params = params.replaceFirst("\"", "");
        params = params.substring(0, params.length() - 1);
    }
    JSONArray jsonArray = JSONArray.parseArray(params);
    if (jsonArray == null || jsonArray.isEmpty()) {
        throw new ProgramException(ErrorCode.PARAM_JSONARRAY, ErrorCode.getErrorMsg(ErrorCode.PARAM_JSONARRAY));
    }

    //1. 解析所有记录，收集 id 与待更新字段；id 必须为纯数字（防注入）
    List<Long> idList = new ArrayList<>();
    //按 id 顺序记录每条的 c_menu_group 值（仅 webmenus/h5menus 受控枚举）
    List<String> menuGroupList = new ArrayList<>();

    for (int i = 0; i < jsonArray.size(); i++) {
        JSONObject jsonObj = jsonArray.getJSONObject(i);
        if (jsonObj == null) {
            continue;
        }
        Object idVal = jsonObj.get("id");
        if (idVal == null) {
            throw new ProgramException(ErrorCode.EXIST_ID,
                    ErrorCode.getErrorMsg(ErrorCode.EXIST_ID).replace("component", "id"));
        }
        //id 必须为纯数字，防 SQL 注入
        String idStr = String.valueOf(idVal).trim();
        if (!idStr.matches("\\d+")) {
            throw new ProgramException(ErrorCode.EXIST_ID,
                    ErrorCode.getErrorMsg(ErrorCode.EXIST_ID).replace("component", "id"));
        }
        long id = Long.parseLong(idStr);
        idList.add(id);

        //c_menu_group：受控枚举值，非白名单值兜底为 webmenus
        String menuGroup = jsonObj.containsKey("c_menu_group") && jsonObj.get("c_menu_group") != null
                ? String.valueOf(jsonObj.get("c_menu_group")).trim() : "webmenus";
        if (!"webmenus".equals(menuGroup) && !"h5menus".equals(menuGroup)) {
            menuGroup = "webmenus";
        }
        menuGroupList.add(menuGroup);
    }
    if (idList.isEmpty()) {
        return 0;
    }

    //2. 批量存在性校验：1 次 SELECT id ... IN(...)
    StringBuilder inSql = new StringBuilder("SELECT id FROM model_dev_db.component_menu WHERE id IN (");
    for (int i = 0; i < idList.size(); i++) {
        if (i > 0) {
            inSql.append(",");
        }
        inSql.append(idList.get(i));
    }
    inSql.append(")");
    List<Map<String, Object>> existResult = commonDAO.get(inSql.toString());
    if (existResult == null || existResult.size() != idList.size()) {
        //找出缺失的 id
        java.util.Set<Long> existIds = new java.util.HashSet<>();
        if (existResult != null) {
            for (Map<String, Object> row : existResult) {
                existIds.add(((Number) row.get("id")).longValue());
            }
        }
        for (Long id : idList) {
            if (!existIds.contains(id)) {
                throw new ProgramException(ErrorCode.SQL_EXIST_ID,
                        ErrorCode.getErrorMsg(ErrorCode.SQL_EXIST_ID).replace("key", "id").replace("value", String.valueOf(id)));
            }
        }
    }

    //3. 批量 UPDATE：1 条 CASE WHEN 语句
    StringBuilder sql = new StringBuilder();
    sql.append("update model_dev_db.component_menu set c_menu_group = case id");
    for (int i = 0; i < idList.size(); i++) {
        sql.append(" when ").append(idList.get(i)).append(" then '").append(menuGroupList.get(i)).append("'");
    }
    sql.append(" end where id in (");
    for (int i = 0; i < idList.size(); i++) {
        if (i > 0) {
            sql.append(",");
        }
        sql.append(idList.get(i));
    }
    sql.append(")");
    int total = commonDAO.update(sql.toString());

    return total;
}
